(()=>{const KEY='lkuni.language';const dictionaries={ru:{language:'RU',logout:'Выйти'},en:{language:'EN',logout:'Sign out'}};function current(){return localStorage.getItem(KEY)||'ru'}function set(lang){const next=lang==='en'?'en':'ru';localStorage.setItem(KEY,next);document.documentElement.lang=next;document.dispatchEvent(new CustomEvent('lkuni:language',{detail:{language:next}}));return next}function toggle(){return set(current()==='ru'?'en':'ru')}function text(key,lang=current()){return dictionaries[lang]?.[key]||dictionaries.ru[key]||key}function bindButton(button){if(!button)return;const render=()=>{button.textContent=current()==='ru'?'RU · EN':'EN · RU';button.setAttribute('aria-label',current()==='ru'?'Switch interface to English':'Переключить интерфейс на русский')};button.addEventListener('click',()=>{toggle();render()});document.addEventListener('lkuni:language',render);render()}window.LkUniI18n={current,set,toggle,text,bindButton};document.documentElement.lang=current()})();